# Alternative idea: What if we're looking at a shearing transformation?
# In shear: new_x = x + k*y, new_y = y

# For our case, maybe: new_col = col + k*row?
# Let's try different k values

def apply_shear(grid, k):
    """Apply horizontal shear with parameter k"""
    new_grid = [[0]*len(grid[0]) for _ in range(len(grid))]
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] != 0:
                new_c = c + k * r
                if 0 <= new_c < len(grid[0]):
                    new_grid[r][new_c] = grid[r][c]
    return new_grid

