import json

def categorize_rows(grid):
    """Categorize rows as top-edge, bottom-edge, or hollow-middleware"""
    h, w = len(grid), len(grid[0])

    nonzero_rows = []
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] != 0]
        if cols:
            nonzero_rows.append((r, cols))

    if not nonzero_rows:
        return {}

    min_r = nonzero_rows[0][0]
    max_r = nonzero_rows[-1][0]
    num_nonzero_rows = len(nonzero_rows)

    result = {
        'min_r': min_r,
        'max_r': max_r,
        'num_rows': num_nonzero_rows,
    }

    output_mapping = {}

    for idx, (r, cols) in enumerate(nonzero_rows):
        dist_from_center = abs(idx - (num_nonzero_rows - 1) // 2)

        if idx == 0:  # Top row
            cat = 'top_edge'
            pred_cols = ['compressed_left']
        elif idx == num_nonzero_rows - 1:  # Bottom row  
            cat = 'bottom_edge'
            pred_cols = ['preserved']
        else:  # Middle rows
            if dist_from_center == 0:
                cat = 'middle_center'
                pred_cols = ['spread_wide']
            elif dist_from_center == 1:
                cat = 'middle_adjacent'
                pred_cols = ['middle_spread']
            else:
                cat = 'outer_middle'
                pred_cols = ['outer_corner']

        output_mapping[idx] = {'cat': cat, 'pred': pred_cols}

    return {**result, 'output_mapping': output_mapping}

